import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Trayecto } from '../../trayectos/entities/trayecto.entity';
import { Conductor } from '../../conductores/entities/conductor.entity';

@Injectable()
export class AsignarConductorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Trayecto) private readonly trayectos: Repository<Trayecto>,
    @InjectRepository(Conductor) private readonly conductores: Repository<Conductor>
  ) {}

  buscarTrayectoRepository(trayectoId: number) {
    return this.trayectos.findOneBy({ id: trayectoId });
  }

  buscarConductorRepository(conductorId: number) {
    return this.conductores.findOneBy({ id: conductorId });
  }

  async asignarConductorRepository(trayectoId: number, conductorId: number, rol: string) {
    const asignacion = { trayectoId, conductorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarConductorRepository } from './repository';

@Injectable()
export class AsignarConductorService {
  constructor(private readonly repository: AsignarConductorRepository) {}

  async asignarConductorService(trayectoId: number, conductorId: number, rol: string) {
    const trayecto = await this.repository.buscarTrayectoRepository(trayectoId);
    const conductor = await this.repository.buscarConductorRepository(conductorId);
    if (!trayecto || !conductor) {
      throw new NotFoundException('No existe el trayecto o el conductor');
    }

    try {
      return await this.repository.asignarConductorRepository(trayectoId, conductorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El conductor ya está asignado a ese trayecto');
      }
      throw error;
    }
  }
}

